let product='Workers',ip='192.0.2.10',zoneTab=0,workerTab=0,account='主账号',billingOK=false;const groups=['Workers','R2','KV','D1'],obj=['worker','bucket','namespace','db'],items=['edge-router','assets-prod','app-config','orders'],sec=(s)=>'<h3 class="section">'+s+'</h3>',panel=s=>'<div class="panel">'+s+'</div>',row=(s,v)=>'<div class="row">'+s+'<small>'+v+'</small></div>',jump=(s,v,id)=>'<a class="row" href="#'+id+'">'+s+'<small>'+v+'　›</small></a>',expand=(s,v,body)=>'<details><summary>'+s+'<small>'+v+'</small></summary><div class="inner">'+body+'</div></details>',button=(s,fn)=>'<button class="mini" onclick="'+fn+'">'+s+'</button>',seg=(names,sel,fn)=>'<div class="segments">'+names.map((s,i)=>'<button class="'+(i===sel?'active':'')+'" onclick="'+fn+'('+i+')">'+s+'</button>').join('')+'</div>',title={domains:'域名',resources:'资源',billing:'账单',accounts:'账号',zone:'example.com',worker:'edge-router',namespace:'app-config',bucket:'assets-prod',db:'orders'};
