function home(){let h='<img class="poster" src="home.png" alt="方案 A 首页">';const data=[[17,162,366,60,'zone'],[17,223,366,60,'worker'],[17,284,366,60,'bucket'],[17,414,118,116,'domains'],[141,414,118,116,'resources','Workers'],[265,414,118,116,'resources','R2'],[17,539,118,116,'resources','KV'],[141,539,118,116,'resources','D1'],...ids.map((id,i)=>[80*i,709,80,65,id])];for(const [x,y,w,k,id,prod]of data)h+='<a class="hot" aria-label="'+(prod||title[id]||'总览')+'" href="#'+id+'" '+(prod?'onclick="product=\''+prod+'\'"':'')+' style="left:'+x/4+'%;top:'+y/7.87+'%;width:'+w/4+'%;height:'+k/7.87+'%"></a>';return h+'<button class="hot" aria-label="切换账号" onclick="chooseAccount()" style="left:55%;top:6%;width:28%;height:6%"></button><button class="hot" aria-label="更多" onclick="showJobs()" style="right:3%;top:6%;width:12%;height:6%"></button>'}
function page(id){switch(id){
case'domains':return sec('已托管')+panel(jump('example.com','已激活','zone'))+'<p class="hint">进入域名即显示 DNS 记录，不再经过功能菜单。</p>';
case'zone':return seg(['DNS','站点设置','安全'],zoneTab,'zt')+(zoneTab===0?sec('解析记录')+panel(expand('www','A · 已代理',row('内容',ip)+row('TTL','自动')+button('编辑记录','editDNS()'))+expand('@','MX · 仅 DNS',row('邮件服务器','mail.example.com')+row('优先级','10'))):zoneTab===1?panel(expand('最低 TLS','1.2',row('当前设置','TLS 1.2'))+expand('名称服务器','Cloudflare',row('NS','ada.ns.cloudflare.com'))):panel(expand('DNSSEC','已启用',row('算法','13'))+row('Universal SSL','已开启')));
case'resources':return '<label class="note">资源类型<select class="product" onchange="product=this.value;render()">'+groups.map(x=>'<option '+(x===product?'selected':'')+'>'+x+'</option>').join('')+'</select></label>'+sec('当前账号')+panel(product==='D1'?row('暂无数据库','0')+jump('查看有数据的示例','仅设计演示','db'):jump(items[groups.indexOf(product)],product,obj[groups.indexOf(product)]));
case'worker':return sec('线上流量')+panel(row('版本 24 / 版本 25','当前部署')+'<div class="bar"><i></i></div>'+row('90% / 10%','部署 #72'))+seg(['部署历史','版本'],workerTab,'wt')+panel(workerTab===0?expand('部署 #72','今天 14:32',row('版本 24','90%')+row('版本 25','10%'))+expand('部署 #71','昨天 18:10',row('版本 24','当时占 100%')+'<small>历史快照，不代表当前流量。</small>'):expand('版本 26','未分配',row('创建时间','今天 14:50'))+expand('版本 25','线上 10%',row('创建时间','今天 14:10'))+expand('版本 24','线上 90%',row('创建时间','昨天 18:03')));
case'namespace':return sec('键')+panel(expand('feature:checkout','键值',row('到期时间','无')+'<div data-private>••••••••</div><button class="quiet" onclick="reveal(this)">查看内容</button>')+expand('theme','键值',row('类型','文本')));
case'bucket':return bucketWork();
case'billing':return sec('账单历史')+(billingOK?panel(row('10 月','USD 5.00')+row('09 月','USD 5.00')):panel('<div class="inner"><h3>无法读取账单历史</h3><p>当前 Token 没有这项读取权限，其他授权不受影响。</p>'+button('查看所需权限','permission()')+'</div>'));
case'accounts':return '<div class="identity"><div class="identityMark" aria-hidden="true"><svg viewBox="0 0 28 28"><path d="M6 20a5 5 0 0 1 0-10 7 7 0 0 1 13-1 5.5 5.5 0 1 1 2 11Z"/></svg></div><div><small>Cloudflare</small><h3>'+account+'</h3></div></div>'+sec('此设备')+panel(expand('应用更新','测试通道',row('当前版本','示例构建'))+expand('操作记录','最近一次',row('DNS 修改','在此核对结果')));
case'db':return databaseWork();default:return ''}}
let bucketTab=0,folder=false,uploaded=new Set(),dbTab=0,sqlRan=false,sqlVisible=false;
const changeArticle=()=>{app.querySelector('article').innerHTML=page(curr());app.querySelector('article').scrollTop=0};
function bt(i){bucketTab=i;changeArticle()}function dt(i){dbTab=i;sqlVisible=false;changeArticle()}
function prefix(v){folder=v;changeArticle()}
function bucketWork(){
 const sub=seg(['对象','配置'],bucketTab,'bt');
 if(bucketTab)return sub+sec('访问与策略')+panel(expand('跨域访问','1 条规则',row('来源','https://example.com')+row('允许方法','GET'))+expand('公共访问','关闭',row('托管域名','未启用'))+expand('生命周期','1 条规则',row('tmp/','30 天后过期')))+'<p class="note">配置留在桶内查看；本原型不修改云端策略。</p>';
 const toolbar='<div class="workTools"><span>'+(folder?'<button class="pathBtn" onclick="prefix(false)">assets-prod</button> / images/':'桶根目录')+'</span>'+button('上传文件','uploadStart()')+'</div>';
 const objrow=(name,size,type)=>expand(name,size,row('对象类型',type)+row('完整键',(folder?'images/':'')+name));
 return sub+toolbar+panel((folder?objrow('logo.svg','18 KB','image/svg+xml'):'<button class="folder" onclick="prefix(true)">images/ <small>文件夹　›</small></button>'+objrow('cover.webp','240 KB','image/webp'))+(uploaded.has(folder?'images/':'root')?objrow('banner.webp','84 KB','image/webp'):''))}
function uploadStart(){openSheet('<h3>上传到当前目录</h3><p class="note">主账号 · assets-prod / '+(folder?'images/':'')+'</p>'+row('示例文件','banner.webp · 84 KB')+'<div class="actions">'+cancel+button('预览上传','uploadPreview()')+'</div>')}
function uploadPreview(){const path=folder?'images/':'root';openSheet('<h3>'+(uploaded.has(path)?'确认覆盖对象？':'确认上传？')+'</h3>'+row('目标桶','assets-prod')+row('目标键',(folder?'images/':'')+'banner.webp')+'<p class="warn">'+(uploaded.has(path)?'示例目录中已存在同名对象，继续将覆盖。':'仅演示上传，不读取设备文件。')+'</p><div class="actions">'+cancel+button(uploaded.has(path)?'模拟覆盖':'模拟上传','uploadDone()')+'</div>')}
function uploadDone(){uploaded.add(folder?'images/':'root');closeSheet();changeArticle();toast('示例对象已显示在当前目录')}
function databaseWork(){const sw=seg(['数据浏览','SQL'],dbTab,'dt');if(!dbTab)return sw+sec('orders · 示例数据库')+panel(expand('orders','4 列',row('id / status','INTEGER / TEXT')+row('amount / created_at','INTEGER / TEXT')+'<div class="tbl"><table><caption>样例行</caption><tr><th>id</th><th>status</th><th>amount</th></tr><tr><td>1001</td><td>paid</td><td>4200</td></tr><tr><td>1002</td><td>pending</td><td>1600</td></tr></table></div>'));
 return sw+sec('SQL 工作区')+'<div class="query"><div>示例语句</div><pre>SELECT id, status\nFROM orders\nLIMIT 2;</pre></div>'+button('核对执行','sqlConfirm()')+(sqlRan?sec('本次结果')+panel('<div class="inner">'+(sqlVisible?'<table><tr><th>id</th><th>status</th></tr><tr><td>1001</td><td>paid</td></tr><tr><td>1002</td><td>pending</td></tr></table>':'<span>••••••••</span>')+' <button class="quiet" onclick="toggleSQL()">'+(sqlVisible?'隐藏结果':'查看结果')+'</button></div>'):'')}
function sqlConfirm(){openSheet('<h3>核对 SQL 执行</h3>'+row('目标','示例数据库 · orders')+'<pre>SELECT id, status FROM orders LIMIT 2;</pre><p class="note">演示只提供这条固定语句，不连接数据库。正式版任意 SQL 仍须确认风险。</p><div class="actions">'+cancel+button('模拟执行','sqlDone()')+'</div>')}
