function zt(i){zoneTab=i;render()}function wt(i){workerTab=i;render()}function reveal(b){const closed=b.textContent==='查看内容';b.previousElementSibling.textContent=closed?'"enabled"':'••••••••';b.textContent=closed?'隐藏内容':'查看内容'}
function render(){const id=curr();if(sheet.open)sheet.close();if(id!=='db')sqlVisible=false;app.className='phone'+(id==='home'?' home':'');if(id==='home'){app.innerHTML=home();return}const group=id==='zone'?'domains':obj.includes(id)?'resources':null;const source=history.state?.navSource;const parent=group?(source&&[...ids,...Object.keys(title)].includes(source)?source:group):null;if(obj.includes(id))product=groups[obj.indexOf(id)];let tab=ids.indexOf(group||id);app.innerHTML='<div class="status"><b>09:41</b><b>▴ ▰</b></div><header><div class="top">'+(parent?'<a class="back" href="#'+parent+'">‹　'+(parent==='home'?'总览':title[parent])+'</a>':(id==='accounts'?'':'<small>'+account+'</small>'))+'</div><h2>'+(title[id]||'总览')+(id==='zone'?' <span class="badge">已激活</span>':'')+'</h2></header><article>'+page(id)+'</article>'+dock(tab)}
document.addEventListener('click',ev=>{const a=ev.target.closest('a[href^="#"]');if(!a||ev.defaultPrevented||ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey)return;const dest=a.hash.slice(1)||'home',from=curr();if(![...ids,...Object.keys(title)].includes(dest))return;ev.preventDefault();if(a.classList.contains('back')&&history.state?.navSource===dest){history.back();return}if(dest===from)return;history.pushState({navSource:from},'',a.hash);render()});
function openSheet(s){sheet.innerHTML=s;if(!sheet.open){history.pushState({sheet:true},'',location.href);sheet.showModal()}}function closeSheet(){if(history.state?.sheet)history.back();else sheet.close()}sheet.oncancel=e=>{e.preventDefault();closeSheet()};window.addEventListener('popstate',()=>{if(sheet.open){sheet.close();return}render()});window.addEventListener('hashchange',render);
const cancel='<button class="quiet" onclick="closeSheet()">取消</button>';
function editDNS(){openSheet('<h3>编辑 DNS 记录</h3><p class="note">主账号 · example.com · www · A</p><label for="addr">IPv4 地址</label><input id="addr" inputmode="decimal" value="'+ip+'"><div class="actions">'+cancel+button('核对变更','reviewDNS()')+'</div>')}
function reviewDNS(){const a=q('#addr'),v=a.value.trim();if(!/^(\d{1,3}\.){3}\d{1,3}$/.test(v)||v.split('.').some(n=>Number(n)>255)||v===ip){a.setCustomValidity('请输入不同的有效 IPv4 地址');a.reportValidity();a.oninput=()=>a.setCustomValidity('');return}openSheet('<h3>确认修改解析</h3><p>主账号 · example.com · www</p>'+row('原地址',ip)+row('新地址',v)+'<p class="note">TTL 和代理状态不变。仅演示，不发云请求。</p><div class="actions">'+cancel+button('确认修改','applyDNS(\''+v+'\')')+'</div>')}
function applyDNS(v){ip=v;closeSheet();const inner=app.querySelector('details[open] .inner');if(inner)inner.innerHTML=row('内容',ip)+row('TTL','自动')+button('编辑记录','editDNS()');toast('已更新示例记录')}
function toast(t){const b=document.createElement('div');b.className='snack';b.setAttribute('role','status');b.textContent=t;app.append(b);setTimeout(()=>b.remove(),2200)}
function showJobs(){openSheet('<h3>最近操作</h3>'+row('主账号 · DNS 修改','已受理')+'<div class="actions">'+button('关闭','closeSheet()')+'</div>')}
function chooseAccount(){openSheet('<h3>当前连接</h3>'+row(account,'✓')+'<p class="note">此原型只使用一个示例账号。</p><div class="actions">'+button('关闭','closeSheet()')+'</div>')}
function permission(){openSheet('<h3>补充账单读取权限</h3>'+row('新增','账号账单历史 · 只读')+row('保留','已核验的原有读取范围')+'<p class="note">实际 App 需要新 Token 验证成功才替换。此处仅演示返回原位置，不接受凭据。</p><div class="actions">'+cancel+button('模拟验证成功','permitted()')+'</div>')}
function permitted(){billingOK=true;closeSheet();app.querySelector('article').innerHTML=page('billing');toast('已回到账单')}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&curr()==='db'&&sqlVisible){sqlVisible=false;changeArticle()}if(document.hidden)app.querySelectorAll('[data-private]').forEach(v=>{v.textContent='••••••••';v.nextElementSibling.textContent='查看内容'})});render()
